import hashlib
import json
import platform
from pathlib import Path

import numpy as np
import pandas as pd
import scipy
from framesignal_metrics import __version__ as metrics_version

from app.analysis.workbench import PLAN, analyze, operating_characteristics, validation_suite


ROOT = Path(__file__).resolve().parents[1]


def percent(value: float) -> str:
    return f"{100 * value:.1f}%"


def main():
    seed = PLAN["seed"]
    print("Running three scenario analyses and 27 independent experiments...", flush=True)
    scenarios = {name: analyze(name, PLAN["households_per_experiment"], seed) for name in ("helpful", "unrelated", "misleading")}
    suite = validation_suite(seed)
    operating = operating_characteristics(seed, PLAN["operating_repetitions"], PLAN["households_per_experiment"])
    provenance = {
        "seed": seed, "plan_sha256": hashlib.sha256((ROOT / "configs" / "analysis_plan.json").read_bytes()).hexdigest(),
        "runtime": {"python": platform.python_version(), "numpy": np.__version__, "pandas": pd.__version__, "scipy": scipy.__version__},
        "metric_library": {"name": "framesignal-metrics", "version": metrics_version},
        "review": "Self-review only; no external peer review occurred.",
    }
    report = {"provenance": provenance, "scenarios": scenarios, "validation": suite, "operating": operating}
    output = ROOT / "reports"
    output.mkdir(exist_ok=True)
    (output / "latest.json").write_text(json.dumps(report, indent=2, allow_nan=False) + "\n", encoding="utf-8")
    lines = [
        "# Metric Validation Report", "", "Generated by `python backend/run_analysis.py` from the frozen v1.0 plan.", "",
        f"Seed: {seed}. {suite['unique_households']:,} distinct households across 27 experiments. Plan SHA-256: `{provenance['plan_sha256']}`.", "",
        "## Estimand and Scope", "",
        "Household-randomized presentation-policy effect on return during days 29-56. All assigned households, including non-viewers, remain in ITT denominators. Synthetic evidence only; not Netflix retention or a content-quality score.", "",
        "## Scenario Results", "", "| Scenario | Starts effect / HH (97.5% CI) | Return effect pp (95% CI) | Oracle return pp | Policy recommendation |",
        "|---|---:|---:|---:|---|",
    ]
    for name, result in scenarios.items():
        starts, target = result["metrics"]["qualified_starts"], result["metrics"]["returned_d29_56"]
        lines.append(f"| {name} | {starts['effect']:+.3f} [{starts['lower']:+.3f}, {starts['upper']:+.3f}] | {100 * target['effect']:+.2f} [{100 * target['lower']:+.2f}, {100 * target['upper']:+.2f}] | {100 * result['truth']['return_effect']:+.1f} | {result['memo']['recommendation']} |")
    lines.extend(["", "The oracle is known DGP truth, not an estimate. A target interval must clear +2 pp to advance; a non-significant estimate is not equivalence.", "", "## Prediction Versus Held-Out Agreement", "", "| Candidate | Held-out mean household correlation | Observed sign agreement | Experiment-bootstrap 95% | Effect-noise sensitivity 95% | Oracle non-null agreement | Null-target positive proxies |", "|---|---:|---:|---:|---:|---:|---:|"])
    heldout = [row for row in suite["experiments"] if row["split"] == "heldout"]
    for metric in ("qualified_starts", "viewing_days"):
        result = suite["agreement"]["heldout"][metric]
        correlation = np.mean([row["prediction"][metric] for row in heldout])
        lines.append(f"| {metric} | {correlation:.3f} | {percent(result['observed_agreement'])} | [{percent(result['lower'])}, {percent(result['upper'])}] | [{percent(result['noise_lower'])}, {percent(result['noise_upper'])}] | {percent(result['oracle_nonnull_agreement'])} | {result['oracle_null_proxy_positive']}/{result['oracle_null_experiments']} |")
    lines.extend(["", "Household correlations reflect latent affinity, not causal mediation. Single-scenario correlations with household-bootstrap intervals and within-arm correlations are in the JSON. Estimated-effect signs under target nulls are unstable. Oracle non-null agreement separates this issue from true reversal.", "", "The experiment bootstrap resamples nine complete experiments. The separate noise sensitivity additionally draws paired candidate/target effects from a correlated Gaussian approximation using household effect covariance. It is not a deconvolved effect regression, a posterior, or definitive surrogate validation; interval calibration is not established for this agreement procedure. Three contrived scenario families are not a representative portfolio.", "", "## Target Inference Operating Characteristics", "", f"{operating['repetitions']:,} independent repeated simulations per effect at N={operating['n']:,}. Rate brackets are 95% Wilson Monte Carlo intervals. Bias uncertainty is Monte Carlo standard error, not a confidence interval.", "", "| True effect pp | Coverage (MC interval) | Null FPR / non-null power (MC interval) | Bias pp ± MC SE | Sampling variance | Mean interval width pp | Practical success |", "|---:|---:|---:|---:|---:|---:|---:|"])
    for row in operating["rows"]:
        coverage, power = row["coverage"], row["rejection_rate"]
        lines.append(f"| {100 * row['true_effect']:.1f} | {percent(coverage['rate'])} [{percent(coverage['lower'])}, {percent(coverage['upper'])}] | {percent(power['rate'])} [{percent(power['lower'])}, {percent(power['upper'])}] | {100 * row['bias']:+.3f} ± {100 * row['bias_mc_se']:.3f} | {row['sampling_variance']:.6f} | {100 * row['mean_interval_width']:.2f} | {percent(row['practical_success']['rate'])} |")
    lines.extend(["", "### Calibration Flags", ""])
    lines.extend(operating["calibration_flags"] or ["No Monte Carlo coverage interval excludes 95% in this run. This is not proof of calibration."])
    lines.extend(["", "These exploratory flags are unadjusted across five effect sizes. They could reflect simulation noise or approximation error; this study does not determine the cause. Preserve the frozen seed and report the observed shortfall rather than claim all coverage checks passed."])
    lines.extend(["", "Operating checks certify neither a candidate metric nor the agreement interval. They assess target difference-in-means inference under this Bernoulli household DGP. With N=2,000, small effects have limited power; the sample size is fixed for the demonstration, not justified as adequate for every 2 pp decision.", "", "## Variance, Failure Modes, and Tradeoffs", "", "- Qualified starts: low latency and straightforward counting, but exposure and attention can inflate the numerator. Positive association does not prevent policy-effect reversal.", "- Viewing days: less runtime-dependent and capped by the window, but repeated short visits can still increase without return benefit; the alternative is not certified.", "- Watch time: heavy-use households and long titles change raw minutes. Pooled 99th-percentile caps, runtime subsets, genre subsets, and shorter windows show sensitivity; each transformation has a distinct estimand.", "- Completion among starters: descriptive household any-completion ratio. Selection occurs after assignment; bootstrap precision does not repair causal selection bias.", "- Exposure: presentation changes impressions. ITT is the total assigned-policy effect. Per-impression results condition on a post-assignment quantity and are diagnostics only.", "", "Household-bootstrap SDs and intervals quantify sampling variation for each run. Full sensitivity estimates, pooled caps, genre mix, exposure balance, and executable SQL queries are in `reports/latest.json`. All integrity checks must pass before interpretation.", "", "## Recommendation", "", suite["decision"], "", "Use the directly observed return target for decisions. Reject a universal starts-only rule. Follow up with new independent, preregistered experiment populations and policy classes; evaluate practical launch decisions, guardrails, equivalence under null, and transportability. Learned composite proxies are deferred until this baseline is reproducible and must respect train/validation/held-out freezing.", "", "## Review Status", "", "Self-review only. No peer review, production inference, real member data, or internal Netflix metric claims. See `docs/methodology_review.md` for critique and revisions."])
    (ROOT / "docs" / "validation_report.md").write_text("\n".join(lines) + "\n", encoding="utf-8")
    memo = ["# Executive Memo", "", "To: Fictional Content and Product stakeholders", "Subject: Do not substitute qualified starts for longer-horizon return", "", "## Recommendation", "", "Keep days 29-56 household return as the decision target. Qualified starts is an operational engagement indicator, not an approved universal surrogate. Viewing days is a useful predefined alternative, but the present evidence does not authorize replacing the target.", "", "## Evidence", ""]
    for name, result in scenarios.items():
        target = result["metrics"]["returned_d29_56"]
        starts = result["metrics"]["qualified_starts"]
        memo.append(f"- {name.title()}: starts {starts['effect']:+.2f}/household; return {target['effect'] * 100:+.2f} pp (95% CI {target['lower'] * 100:+.2f} to {target['upper'] * 100:+.2f}). {result['memo']['recommendation']}.")
    agreement = suite["agreement"]["heldout"]["qualified_starts"]
    memo.extend(["", f"Starts has {percent(agreement['observed_agreement'])} observed held-out sign agreement across only nine experiments (experiment-bootstrap interval {percent(agreement['lower'])}-{percent(agreement['upper'])}). This is descriptive; noisy signs and constructed scenarios prevent surrogate certification.", "", "## What Not to Conclude", "", "This is fictional randomized presentation-policy evidence, not a Netflix retention definition, internal content metric, or claim that a show caused return. Completion among starters compares selected post-assignment populations. Positive household prediction is not causal surrogacy. No title receives an artistic-value score.", "", "## Next Decision", "", "Run new independently populated, preregistered policy experiments with justified power for a +2 pp practical threshold, a direct longer-horizon target, and guardrails. Do not repeatedly inspect fixed-sample p-values or extend this run until significant. Evaluate nulls with predefined equivalence margins rather than calling non-significance no effect. Obtain genuine peer review before any external application.", "", "Evidence and uncertainty: `docs/validation_report.md` and `reports/latest.json`. Self-review only; no peer feedback occurred."])
    (ROOT / "docs" / "executive_memo.md").write_text("\n".join(memo) + "\n", encoding="utf-8")
    print(f"Wrote {output / 'latest.json'}, validation report, and executive memo.", flush=True)
    print(json.dumps({"sql_passed": all(row["sql"]["passed"] for row in scenarios.values()), "unique_households": suite["unique_households"], "heldout_starts_agreement": agreement["observed_agreement"], "null_fpr": operating["rows"][0]["rejection_rate"]["rate"]}, indent=2))


if __name__ == "__main__":
    main()